-- Placeholders like {{ run_id }} are filled in by the ELT DAG at run time.
-- Adds one f_<check> column per rule, plus dq_status, failure_reason, warning_reason
CREATE OR REPLACE TABLE stg_stores_flagged AS
SELECT *,
  CASE WHEN "f_store_id_not_null" OR "f_store_id_unique" THEN 'FAIL' WHEN "f_zone_allowed" OR "f_store_pincode_format" OR "f_capacity_positive" THEN 'WARN' ELSE 'PASS' END AS dq_status,
  NULLIF(concat_ws('; ', CASE WHEN "f_store_id_not_null" THEN 'store_id_not_null' END, CASE WHEN "f_store_id_unique" THEN 'store_id_unique' END), '') AS failure_reason,
  NULLIF(concat_ws('; ', CASE WHEN "f_zone_allowed" THEN 'zone_allowed' END, CASE WHEN "f_store_pincode_format" THEN 'store_pincode_format' END, CASE WHEN "f_capacity_positive" THEN 'capacity_positive' END), '') AS warning_reason
FROM (
  SELECT t.*,
    COALESCE((t.store_id IS NULL), FALSE) AS "f_store_id_not_null",
    COALESCE((t.store_id IS NOT NULL AND row_number() OVER (PARTITION BY t.store_id ORDER BY t._row) > 1), FALSE) AS "f_store_id_unique",
    COALESCE((t.zone IS NULL), FALSE) AS "f_zone_allowed",
    COALESCE((t.pincode IS NOT NULL AND NOT regexp_full_match(t.pincode, '[0-9]{6}')), FALSE) AS "f_store_pincode_format",
    COALESCE((t.capacity_orders_per_day IS NULL OR t.capacity_orders_per_day <= 0), FALSE) AS "f_capacity_positive"
  FROM stg_stores_std t
) AS flagged;
